public class ParallelRunnerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        Counter solo = new Counter();
        check("a new counter starts at zero", 0, solo.get());
        solo.increment();
        solo.increment();
        solo.increment();
        check("three increments on one thread", 3, solo.get());

        Counter small = new Counter();
        check("4 threads x 1000 increments", 4000, ParallelRunner.runConcurrently(small, 4, 1000));
        check("the shared counter agrees with the return value", 4000, small.get());

        check("running again keeps counting up", 6000, ParallelRunner.runConcurrently(small, 2, 1000));

        Counter busy = new Counter();
        check("8 threads x 25000 increments loses nothing", 200000,
                ParallelRunner.runConcurrently(busy, 8, 25000));

        Counter idle = new Counter();
        check("zero threads does no work", 0, ParallelRunner.runConcurrently(idle, 0, 500));
        check("zero increments each does no work", 0, ParallelRunner.runConcurrently(idle, 4, 0));
        check("one thread still works", 7, ParallelRunner.runConcurrently(idle, 1, 7));

        Counter finished = new Counter();
        int reported = ParallelRunner.runConcurrently(finished, 6, 5000);
        check("6 threads x 5000 increments", 30000, reported);
        check("nothing was still running when it returned", 30000, finished.get());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

